%[text] %[text:anchor:T_EF5120B5] # Spike Artifacts
%[text] Investigate how tACS stimulation artifacts affect spike recordings.
%[text:tableOfContents]{"heading":"**Table of Contents**"}
%%
%[text] %[text:anchor:H_9BC26763] ## Setup Simulation
%[text] Simulation parameters
startup; % Make sure all toolboxes are on the path
clear spkDefaults arDefaults % Avoid lingering values from prevoous runs
spkDefaults.duration                  = 120;    % 2 min
spkDefaults.stimulatorSamplingRate    = 1e3;     % e.g., Starstim (1 kHz)
spkDefaults.currentResolution         = 1e-6;    % 1 muA
spkDefaults.resistance                = 1;        % 1 mA -> 1 mV artifact
spkDefaults.recordingSamplingRate     = 30e3;     % 30kHz
spkDefaults.adcLinearRange            = 6.8e-3;   % Linear range of amplified 6.8 mV
spkDefaults.adcNonlinearity           = 100;      % Piecewise linear
spkDefaults.adcRange                  = 10e-3;     % Input range of the ADC.
spkDefaults.adcBitDepth               = 16;       % Number of bits in the AD convertor
spkDefaults.adcGain                   = 20;       % Amplify 20x
spkDefaults.highPass                  = 0.01;     % High pass filter on the preamp. 
spkDefaults.reproducible              = 2;       % Seed the RNG to get reproducible results
%[text] Define the common neural signals
spkDefaults.spikePeak                 = 60e-6;   % 60 muV
spkDefaults.spikeRate                 = 100;      % 100 spk/s
spkDefaults.poisson                           = true;     % Poisson spiking
spkDefaults.fixNrSpikes               = true;     % Deviate from Poisson to get exact firing rate.
spkDefaults.refractoryPeriod          = 1.5e-3;   % 1.5 ms
spkDefaults.additive                  = 20e-6;    % Background activity/noise
spkDefaults.pinkNoise                 = true;     % Pink background noise
spkDefaults.synchrony                 = 0;        % Poisson random spikes, no relation with LFP
spkDefaults.lfpAmplitude              = 0;        % No intrinsic oscillation
spkDefaults.multiplicative            = 0;        % No multiplicative noise

%[text] Define the common parameters for artifact removal
arDefaults.slide                     = false;   % No sliding segment
arDefaults.slack                     = 5e-3;    % 5 ms to realign segments
arDefaults.nrSegsPerWindow           = 10;      % 10 segments to average artifact
arDefaults.pcaNr                     = 2;       % First two PC are removed
arDefaults.pcaVarExplained           = Inf;     % Ignore explained variance, always remove 2.
arDefaults.pcaNrSegsPerWindow        = Inf;     % Use all segments (plus the tACS signal; below) to determine basis set.
arDefaults.referenceSegment          = 1;       % Align to first segment
arDefaults.recordingSamplingRate      = spkDefaults.recordingSamplingRate; % Match to the recording
%[text] Define the filter that extract signals in the "spike band":
lowCut                      = 500;  % high pass filter cut off
highCut                     = 7000; % Low pass filter cut off.
filterOrder                 = 3; % Filter order  (Butterworth)
%%
%[text] ## Stimulator Discretization Artifacts
%[text] With typical tACS frequencies below 100 Hz and typical spiking signals near 1 kHz, one might expect that a simple high-pass filter would remove all tACS artifacts from the signal used for spike-based analysis. This is indeed the case for an ideal stimulator that genreates sinusoidal waveforms with high temporal resolution. Stimulators, however, typically use a sampled D2A converter to generate currents and such sampled sinusoids can generate artifacts in the spike band. 
%[text] To illustrate this I simulated a stimulator with a 1 kHz sampling rate, and 1 muA current resolution and a  1mA tACS artifact.
spk                   = artSim(spkDefaults);
spk.tacsAmplitude     = 1e-3;    % 1 mA for illustration
spk.tacsFrequency     = 40;
spk.tacsPhaseOffset   = 0.5*pi;
spk.reset;
spk.simTCS;
%[text] The simulation has now created the `vTcsActual` - the voltage artifact created by this stimulator. 
%[text] Visualizing just two cycles of the waveform illustrates the problem: 
[~,axs] = fig('Name','Fig8','paperCols',2,'height',9,'nrRows',2,'nrCols',3,'byColumn',false); %[output:3228d1e0]
%[text] Show the voltage artifact
nrCyclesToShow = 2;
axes(axs(1)) %[output:3228d1e0]
plot(spk.tSimulate/1e-3,spk.vTcsActual/1e-3) %[output:3228d1e0]
xl = [0 nrCyclesToShow/spk.tacsFrequency/1e-3];
xlim (xl); %[output:3228d1e0]
xlabel 'Time (ms)' %[output:3228d1e0]
ylabel 'Voltage (mV)' %[output:3228d1e0]
axs(1).XTick = xl; %[output:3228d1e0]

%[text] and its amplitude spectrum
axes(axs(2)) %[output:3228d1e0]
[ft,frequency]= fftReal(spk.vTcsActual(:),spk.quasiContinuousSamplingRate);
amplitude =abs(ft)./(2*numel(spk.vTcsActual));

plot(frequency/1e3,amplitude/1e-6); %[output:3228d1e0]
xlabel 'Frequency (kHz)' %[output:3228d1e0]
ylabel 'Amplitude (\muV)' %[output:3228d1e0]
xlim([lowCut highCut]/1e3) %[output:3228d1e0]
%[text] The spectral power shows that the artifact is not stationary, but varies with tACS phase
axes(axs(3)) %[output:3228d1e0]
% Spectrogram
boundaryCycles =4;
samplesPerCycle = spk.quasiContinuousSamplingRate./spk.tacsFrequency;
keep = 1:round(nrCyclesToShow*samplesPerCycle)+boundaryCycles*samplesPerCycle;
x = spk.vTcsActual(keep);
[ft,freq]= fftReal(x,spk.quasiContinuousSamplingRate);
ft(freq<lowCut | freq>highCut) =0;
x = ifftReal(ft,freq,spk.quasiContinuousSamplingRate);
pspectrum(x,spk.quasiContinuousSamplingRate,'spectrogram','FrequencyResolution',500,'FrequencyLimits',[0 highCut]) %[output:3228d1e0]

xlim([50 100]) %[output:3228d1e0]
axs(3).XTick =[50 75 100]; %[output:3228d1e0]
axs(3).YTick =[lowCut/1e3 1:highCut/1e3]; %[output:3228d1e0]
axs(3).XTickLabel = {'0','25','50'}; %[output:3228d1e0]
ylim([lowCut highCut]/1e3) %[output:3228d1e0]
colorbar('off') %[output:3228d1e0]
title '' %[output:3228d1e0]
colormap hot %[output:3228d1e0]
%[text] Add a polar representation of the peak of the artifact to illustrate the phase dependence
trgPos = get(axs(4),'Position');
trgPos([1 2]) = trgPos([1 2]).*[0.7 0.9];
pax = polaraxes('Position',trgPos); %[output:3228d1e0]
axes(pax); %[output:3228d1e0]
[P,F,T] = pspectrum(x,spk.quasiContinuousSamplingRate,'spectrogram','FrequencyResolution',500,'FrequencyLimits',[0 highCut]);
oneCycle =T>=3/spk.tacsFrequency & T< 4/spk.tacsFrequency;

P =sum(P(:,oneCycle)); % Sum one cycle over the spike band
phase = spk.tacsPhaseOffset+ linspace(0,2*pi*(1-1/numel(P)),numel(P)+1);
P = [P P(1)];
polarplot(phase,P) %[output:3228d1e0]

pax.RTick = []; %[output:3228d1e0]
pax.ThetaTick = [0 90 180 270]; %[output:3228d1e0]
pax.Color = 'w';
delete(axs(4)) %[output:3228d1e0]

%[text] And illustrate that the power in the spike band increases (linearly) with the tACS frequency
tacsFreqs                    = [2 5 10 20 40];
nrTacsFreqs                  = numel(tacsFreqs);
artifactPower = nan(nrTacsFreqs,1);
for i = 1:nrTacsFreqs
    spk.tacsFrequency             =tacsFreqs(i);
    spk.reset;
    spk.simTCS;
    [ft,frequency]= fftReal(spk.vTcsActual(:),spk.quasiContinuousSamplingRate);
    % Remove the power that would be filtered out
    ft(frequency < lowCut | frequency > highCut) = 0;
    signal = ifftReal(ft,frequency,spk.quasiContinuousSamplingRate);
    artifactPower(i) = max(abs(signal));
end
axes(axs(5)) %[output:3228d1e0]
plot(tacsFreqs,artifactPower./1e-6) %[output:3228d1e0]
xlabel 'tACS Frequency (Hz)' %[output:3228d1e0]
ylabel 'Artifact (\muV)' %[output:3228d1e0]
%[text] Finally, show the shape of the artifact at selected tACS phases.

samplesPerCycle = spk.quasiContinuousSamplingRate./spk.tacsFrequency;
axes(axs(6)) %[output:3228d1e0]
% Bandpass filter to take only the signal in the spike band
[B,A] = butter(filterOrder,[lowCut highCut]/(spk.quasiContinuousSamplingRate/2),'bandpass');
filteredVoltage   = filtfilt(B,A,spk.vTcsActual(:));
% Select a time window similar to a spike 
samplesToShow     = 1e-3*spk.quasiContinuousSamplingRate; %  1 ms
samplesBefore     = round(0.5*samplesToShow);
samplesAfter      = samplesToShow-samplesBefore;
phase             = [0 90 180 270];
offset            = round(samplesPerCycle*(rad2deg(2*pi-spk.tacsPhaseOffset)/360));
t                 = (-samplesBefore:samplesAfter)/spk.quasiContinuousSamplingRate;
for ph=phase
    ix = offset+ round(samplesPerCycle*ph/360) + (-samplesBefore:samplesAfter);
    plot(t/1e-3,filteredVoltage(ix)/1e-6); %[output:3228d1e0]
    hold on
end
xlabel 'Time (ms)' %[output:3228d1e0]
ylabel 'Votlage (\muV)' %[output:3228d1e0]
legend(string(num2str(phase')) + "^\circ","Position", [0.74 0.31 0.12, 0.14]) %[output:3228d1e0]
legend('boxoff') %[output:3228d1e0]
%%
%[text] %[text:anchor:H_1C3B008F] ## Spike Sorting 
%[text] Spike sorting labels spikes as belonging to a specific neuron and is often used to focus analysis on one (or more) identified neurons with recognizable wave forms. This process is standard, but in the context of stimulation artifacts, there is a potential that the spike sorting procedure masks (rather than removes) the effects of stimulation. These simulations explore that using the UMS2K spike sorter (although the details of spike sorting are unlikely to change the overall message).
%[text] Define the neural signals:
spk = artSim(spkDefaults);
ar = arDefaults;
spk.tacsAmplitude             = 120e-6;   % A->V artifact
spk.tacsFrequency             = 40;

%[text] In most approaches, the spike detection threshold is defined relative to some noise level that is estimated from the signal in the spike band. The simulations generate one trial with tACS and one trial without tACS (but the same spikes). By setting `sharedThreshold` to `true, the v`oltage threshold is estimated from the concatenated signals in the spike band (i.e., with and without tACS).  Note that this creates an interaction between spike detection in trials with and without tACS. Notably, if tACS generates large artifacts in the spike band, the voltage threshold will be high and true spikes -even in trials without stimulation -  could be lost  resulting in false negatives even in sham trials. 
%[text] The spike detection can be changed to use a separate threshold for stimulated and non-stimulated trials (`sharedThreshold = false`) - although this creates its own issues in the interpretation of the results.
threshold                      = 3.5 ; % Spikes are defined as this many standard deviations above zero.
sharedThreshold                = true;
%[text] After spike detection, UMS2K extracts a waveform for each spike to determine clusters based on the waveform shape. (This too leads to an interaction between tACS contaminated and tACS-free spikes).
nrPre                           = 1e-3*spk.recordingSamplingRate; % Samples to keep before threshold crossing
nrPost                          = nrPre; % Samples to keep after threshold crossing
%[text] ArtSim can use different methods to do spike sorting. ALL  means no spike sorting; it returns all threshold crossings. In MATCHSHAM mode, spikes in the tACS trial are compared to the clusters found in the no-tACS trial and assigned to the best-matching cluster. MOSTSPIKES keeps only the unit with the most spikes. Investigate spike detection first:
spikeSortingMode                ="ALL";
%[text] Run the simulation to illustrate the problem caused by stimulation artifacts in a pipeline that only filters to the spike band (i.e. without other artifact removal). 
[~,axs] = fig('Name',"Fig9",'paperCols',2,'height',12,'nrRows',2,'nrCols',2,'byColumn',false);    %[output:9f1599ac]
[sortResultsNopAll]  = simPlotSpikes(spk,ar,"NOP",xlim = 8+[0 0.1],lowCut=lowCut,highCut=highCut,filterOrder=filterOrder,threshold=threshold,sharedThreshold = sharedThreshold, spikeSortingMode=spikeSortingMode,axs=[axs(1:2)' gobjects(2)]); %[output:7cd7eb15] %[output:9f1599ac]
%[text] This figure shows the voltage trace filtered to the spike band (red), the ground truth spikes (circle), and the detected spikes (asterisk) for a snippet from the no-tACS trial (a) and the tACS trial (b). Panel c shows a polar histogram of the spikes as a function of the phase of tACS.  In the sham trial all phases are equally likely, in the tACS trial, the 0 and 180 degree phases are less likely to result in a detected spike. Panel d shows that the average waveform of the sorted spikes does not depend on the phase. 
%[text] The phase dependence arises due to the larger current steps near the 180 and 0 phases. Differences between 180 and 0 can occur if the spike threshold detection algorithm treates negative going deflections differently form positive deflections. 
spikeSortingMode                ="MATCHSHAM";
%[text] Run the simulation to illustrate the problem caused by stimulation artifacts in a pipeline that only filters to the spike band (i.e. without other artifact removal). 
 [sortResultsNop]  = simPlotSpikes(spk,ar,"NOP",lowCut=lowCut,highCut=highCut,filterOrder=filterOrder,threshold=threshold,sharedThreshold = false, spikeSortingMode=spikeSortingMode,axs=[gobjects(1:2) axs(3:4)]); %[output:9288eaf4] %[output:9f1599ac]
%[text] In these simulations there are no false positive  (i.e. sorted spikes found where none were simulated), but false negatives are quite frequent; not only in the tACS trial (32%), but also in the Control/Sham trial (5%). The latter is a consequence of using a single spike threshold and spike template estimation - this results in a contamination of the spike sorting process in the sham trial.
%[text] Taken together, these stimulation show that merely filtering to the spike band is not sufficient to remove spike artifacts. 
%%
%[text] %[text:anchor:H_0F76CEFC] ### Spike Sorting with FASTR 
%[text] Run the same spike sorting pipeline now with FASTR recovery of the underlying neural signal.   
 [sortResultsFASTR] = simPlotSpikes(spk,ar,"FASTR",lowCut=lowCut,highCut=highCut,filterOrder=filterOrder,threshold=threshold,spikeSortingMode=spikeSortingMode); %[output:29887164] %[output:906eda1e] %[output:9f0c8d8f] %[output:9b65ac5a] %[output:9e5c9b57]
%[text] This shows FASTR helps to recover true spiking. But note that some false negatives remain.  
%%
%[text] ### Spike sorting with RBAR
[sortResultsRBAR] = simPlotSpikes(spk,ar,"RBAR",lowCut=lowCut,highCut=highCut,filterOrder=filterOrder,threshold=threshold,spikeSortingMode=spikeSortingMode); %[output:37dbd57a] %[output:0b92618e] %[output:0ac21bb1]
%[text] RBAR recovers the spikes; with zero false negatives.
%%
%[text] %[text:anchor:H_261845DF] ## Amplifier Saturation
%[text] Simulate what happens if spikes are pushed into the nonlinear range of the amplifier. 
spk = artSim(spkDefaults);
ar = arDefaults;
%[text] Set the amplifier properties to saturate
spk.adcNonlinearity           = 4;   % Sigmoidal
spk.resistance                = 45;  % Increase voltage artifact to reach the nonlinear range.
spk.stimulatorSamplingRate    = 1e6;  % Remove stimulator discretization artifact to focus on amp saturation
%[text] Set the tACS properties  and run simulation
spk.tacsAmplitude             = 120e-6;  
spk.tacsFrequency             = 40;
spikeSortingMode              = "ALL";

[~,axs] = fig('Name',"Fig11",'paperCols',1.5,'height',4,'nrRows',1,'nrCols',2,'byColumn',true); %[output:77a769b9]
[sortResultsRBARNonLin] = simPlotSpikes(spk,ar,"NOP",nrPhaseBins =8, phaseFromRaw = true,lowCut=lowCut,highCut=highCut,filterOrder=filterOrder,threshold=threshold,spikeSortingMode=spikeSortingMode,axs=[gobjects(1:2)';axs]); %[output:1f9871d9] %[output:77a769b9]
%[text] Show the saturation (illustrating that it can be subtle)
[~,axs] = fig('Name',"Fig10",'paperCols',1,'height',4,'nrRows',1,'nrCols',1);

axes(axs(1))
yyaxis left
in = linspace(-spk.adcRange,spk.adcRange,100);
[out,satPoint] = artSim.amplify(in,spk.adcLinearRange,spk.adcNonlinearity,spk.adcGain,satLevel = 95);
scale = (1e-3*spk.adcGain);
plot(in/1e-3,out/scale,'LineWidth',1.5)
hold on
plot(in/1e-3,in/1e-3,'LineWidth',1,'LineStyle',':')
xlabel 'Input Voltage (mV)'
ylabel 'Output Voltage (mV)'
plot(satPoint/1e-3*[1 1],ylim,'k:')
plot(-satPoint/1e-3*[1 1],ylim,'k:')

[n,vBins] = histcounts(spk.vContaminated/scale,10);
yyaxis right
bar(vBins(1:end-1),n./max(n));
ylim([0 2]);
set(gca,'YTick',[0 0.5 1])
ylabel 'Relative Probability'

%%
